mapper.select:
SELECT id
  FROM tbl_user_mission_info
 WHERE user_id = #{userId}
   AND assign_date < #{beforeDate}
   AND result = 'PENDING'
 ORDER BY assign_date, id

mapper.update:
UPDATE tbl_user_mission_info
   SET result = #{result},
       evaluated_at = #{evaluatedAt}
 WHERE id = #{assignmentId}
   AND result = 'PENDING'
